  315 => 
  array (
    'id' => 'collectible-4796',
    'name' => 'Пропуск зрителя PGL Major Stockholm 2021',
    'description' => 'Это неоткрытый пропуск зрителя на мейджор-турнир PGL Major Stockholm 2021 по CS:GO. Открыв его, вы получите монету, засчитывающую ваши успехи на протяжении турнира, а также дающую доступ к прогнозам, метке для чата Steam.tv, внутриигровым испытаниям и неограниченным граффити команды на время турнира.\\n\\nЧтобы улучшить монету турнира, проходите её испытания. Вы получите по сувенирному жетону за каждое улучшение монеты.\\n\\n50% от продаж этого пропуска получают организации-участницы турнира.',
